definitions.definition:
#[derive(Copy, Clone, PartialEq, Eq, Hash, Debug)] pub struct DefId(pub u32);
#[derive(Copy, Clone, PartialEq, Eq, Hash, Debug)] pub struct ContextId(pub u32); // global across the repository
#[derive(Copy, Clone, PartialEq, Eq, Hash, Debug)] pub struct FormatId(pub u16);  // global
#[derive(Copy, Clone, PartialEq, Eq, Hash, Debug)] pub struct KeywordListId(pub u16);
#[derive(Copy, Clone, PartialEq, Eq, Hash, Debug)] pub struct FoldId(pub u16);

pub struct Definition {
    pub name: String, pub section: String, pub version: u32, pub priority: i32, pub hidden: bool,
    pub extensions: Vec<String>, pub mime_types: Vec<String>,
    pub case_sensitive_keywords: bool, pub indenter: Option<String>,
    pub word_delimiters: WordDelimiters,
    pub comments: Vec<CommentStyle>,
    pub indentation_based_folding: bool,
    pub initial_context: ContextId,
    pub contexts: std::ops::Range<u32>, // this definition's slice of Repository::contexts
    pub formats: std::ops::Range<u16>,
    pub license: String,            // verbatim from the XML `license` attribute; vendoring policy depends on it
}

pub struct WordDelimiters { pub delimiters: Vec<char>, pub weak: Vec<char> }
pub enum CommentStyle { SingleLine { start: String, position: CommentPosition }, MultiLine { start: String, end: String } }
pub enum CommentPosition { Anywhere, AfterWhitespace }

pub struct Context {
    pub name: String,
    pub attribute: FormatId,
    pub rules: Vec<Rule>,
    pub line_end: ContextSwitch, pub line_empty: ContextSwitch, pub fallthrough: Option<ContextSwitch>,
    pub no_indentation_based_folding: bool, pub stop_empty_line_context_switch_loop: bool,
}

#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum ContextSwitch { Stay, Pop(u8), Push(ContextId), PopPush(u8, ContextId) }

pub struct Rule {
    pub kind: RuleKind, pub attribute: Option<FormatId>, pub switch: ContextSwitch,
    pub lookahead: bool, pub first_non_space: bool, pub column: Option<u32>,
    pub begin_region: Option<FoldId>, pub end_region: Option<FoldId>, pub dynamic: bool,
}

pub enum RuleKind {
    AnyChar(Vec<char>), DetectChar(char), Detect2Chars(char, char), DetectIdentifier, DetectSpaces,
    Float, Int, HlCChar, HlCHex, HlCOct, HlCStringChar,
    Keyword { list: KeywordListId, insensitive: bool },
    LineContinue(char), RangeDetect(char, char),
    RegExpr { pattern: String, insensitive: bool, minimal: bool }, // compiled lazily in PKT-0008
    StringDetect { text: String, insensitive: bool }, WordDetect { word: String, insensitive: bool },
}

pub struct KeywordList { pub name: String, pub words: Vec<String> } // sorted, deduplicated; includes resolved `<include>`

pub struct Format {
    pub name: String, pub style: DefaultStyle,
    pub color: Option<Rgb>, pub selected_color: Option<Rgb>, pub background: Option<Rgb>, pub selected_background: Option<Rgb>,
    pub bold: Option<bool>, pub italic: Option<bool>, pub underline: Option<bool>, pub strikeout: Option<bool>,
    pub spell_check: bool,
}
#[derive(Copy, Clone, PartialEq, Eq, Debug)] pub struct Rgb(pub u8, pub u8, pub u8);

/// The 30 default text styles of KSyntaxHighlighting (dsNormal .. dsOthers), same order.
#[derive(Copy, Clone, PartialEq, Eq, Hash, Debug)]
pub enum DefaultStyle { Normal, Keyword, Function, Variable, ControlFlow, Operator, BuiltIn, Extension, Preprocessor, Attribute, Char, SpecialChar, String, VerbatimString, SpecialString, Import, DataType, DecVal, BaseN, Float, Constant, Comment, Documentation, Annotation, CommentVar, RegionMarker, Information, Warning, Alert, Error, Others }

pub struct Repository {
    definitions: Vec<Definition>,
    contexts: Vec<Context>,          // dense; ContextId indexes here
    formats: Vec<Format>,
    keyword_lists: Vec<KeywordList>,
    fold_names: Vec<String>,
    by_name: std::collections::HashMap<String, DefId>,
}
impl Repository {
    pub fn empty() -> Self;
    /// Parses one definition. Cross-definition references (`Name##Other`) are recorded and resolved by `link`.
    pub fn add_xml(&mut self, xml: &str) -> Result<DefId, LoadError>;
    /// Resolves IncludeRules, context references and keyword includes. Errors name the definition and context.
    pub fn link(&mut self) -> Result<(), LoadError>;
    pub fn definition(&self, id: DefId) -> &Definition;
    pub fn context(&self, id: ContextId) -> &Context;
    pub fn format(&self, id: FormatId) -> &Format;
    pub fn keyword_list(&self, id: KeywordListId) -> &KeywordList;
    pub fn by_name(&self, name: &str) -> Option<DefId>;
    /// Highest-priority definition whose extensions glob matches the file name.
    pub fn for_file_name(&self, name: &str) -> Option<DefId>;
    pub fn for_mime_type(&self, mime: &str) -> Option<DefId>;
}

#[derive(Debug)]
pub enum LoadError {
    Xml { definition: Option<String>, line: u64, message: String },
    UnknownContext { definition: String, context: String, reference: String },
    UnknownKeywordList { definition: String, list: String },
    UnknownFormat { definition: String, format: String },
    DuplicateDefinition { name: String },
}
